// Live values — the three numbers and the mode driving both curve families.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  mode:  val('mode'),   // string — the branch selector
  a:     val('a'),      // number
  b:     val('b'),      // number
  delta: val('delta'),
  ratio: nb.get('a') + ':' + nb.get('b'),  // the a:b ratio is what shapes both families
};
